if (!document.documentElement.classList.contains('ai4a11y-bigger-targets')) return true;

function getEffectiveRect(el) {
  const r = el.getBoundingClientRect();
  const mark = el.getAttribute('data-ai4a11y-bt') || '';
  if (mark.includes('hit')) {
    const after = window.getComputedStyle(el, '::after');
    const t = Math.abs(parseFloat(after.top) || 0);
    const b = Math.abs(parseFloat(after.bottom) || 0);
    const l = Math.abs(parseFloat(after.left) || 0);
    const rt = Math.abs(parseFloat(after.right) || 0);
    return {
      left: r.left - l,
      right: r.right + rt,
      top: r.top - t,
      bottom: r.bottom + b,
      width: r.width + l + rt,
      height: r.height + t + b
    };
  }
  return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height };
}

const targets = [...document.querySelectorAll('a[href], button, input, select, textarea, summary, [role="button"], [role="link"]')]
  .filter(el => {
    if (el.disabled || el.getAttribute('type') === 'hidden') return false;
    const cs = window.getComputedStyle(el);
    return cs.display !== 'none' && cs.visibility !== 'hidden' && cs.opacity !== '0';
  });

for (let i = 0; i < targets.length; i++) {
  for (let j = i + 1; j < targets.length; j++) {
    const a = targets[i], b = targets[j];
    if (a.contains(b) || b.contains(a)) continue;
    const rA = getEffectiveRect(a), rB = getEffectiveRect(b);
    const overlapX = rA.left < rB.right - 0.5 && rA.right > rB.left + 0.5;
    const overlapY = rA.top < rB.bottom - 0.5 && rA.bottom > rB.top + 0.5;
    if (overlapX && overlapY) return false;
  }
}
return true;
